{"path": "/home/daytona/daytona_quickstart.ts", "content": "import { Daytona } from '@daytona/sdk';

function sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function main() {
    // Initialize the SDK (uses environment variables by default)
    const daytona = new Daytona();

    // Create a new sandbox
    console.log("Creating sandbox...");
    const sandbox = await daytona.create({
        language: 'typescript',
    });
    console.log(`Sandbox created: id=${sandbox.id}`);

    // Wait for sandbox to be fully ready
    console.log("Waiting 30 seconds for sandbox to be fully ready...");
    await sleep(30000);

    // Execute a command with retries
    console.log("Running command inside the sandbox...");
    for (let attempt = 1; attempt <= 5; attempt++) {
        try {
            const response = await sandbox.process.executeCommand('echo "Hello, World!"');
            console.log(`Command result: ${response.result}`);
            break;
        } catch (e: any) {
            console.log(`Attempt ${attempt} failed: ${e.message}`);
            if (attempt < 5) {
                await sleep(10000);
            } else {
                throw e;
            }
        }
    }

    // Clean up
    console.log("Deleting sandbox...");
    await sandbox.delete();
    console.log("Sandbox deleted.");
}

main().catch(console.error);
"}
